package com.m3mo.vault.domain.model

/**
 * MemoryItem - Core domain model for M3mo
 *
 * Represents a single memory in the vault. This is an immutable value object
 * following DDD principles. All modifications create new instances.
 *
 * Key design decisions:
 * - Immutable: Ensures thread-safety and predictable state
 * - Uses Long IDs: Generated by IdGenerator (Snowflake algorithm)
 * - Weight-based priority: SmartDecay algorithm adjusts weight over time
 * - Vector-ready: Embedding stored for semantic search
 */
data class MemoryItem(
    /**
     * Unique identifier (Snowflake ID from IdGenerator)
     */
    val id: Long,

    /**
     * Raw content as entered by user
     */
    val content: String,

    /**
     * Normalized content for search/matching
     * May include stemming, lowercasing, etc.
     */
    val normalizedContent: String,

    /**
     * Memory type classification
     */
    val type: MemoryType,

    /**
     * Processing state in the pipeline
     */
    val state: ProcessingState,

    /**
     * Weight for SmartDecay algorithm (1-16 scale)
     * Used by maintenance rules and search scoring.
     */
    val weight: Int,

    /**
     * User-pinned memories don't decay
     */
    val isPinned: Boolean,

    /**
     * User confidence rating (1-5, null if not rated)
     */
    val confidence: Int?,

    /**
     * Task completion state (only for TASK type)
     */
    val isCompleted: Boolean,

    /**
     * Number of times this memory was accessed/recalled
     */
    val accessCount: Int,

    /**
     * Embedding vector for semantic search (serialized as JSON string)
     * Null if not yet vectorized
     */
    /**
     * Semantic embedding vector (binary format for efficiency)
     * 
     * Stored as ByteArray (BLOB) instead of JSON String for:
     * - 60%+ storage reduction
     * - 10x faster parsing
     * - Zero Base64 encoding overhead
     */
    val embedding: ByteArray?,

    /**
     * Source of this memory (voice, text, import, etc.)
     */
    val source: MemorySource,

    /**
     * Optional tags for categorization
     */
    val tags: List<String>,

    /**
     * Timestamps
     */
    val createdAt: Long,
    val updatedAt: Long,
    val lastAccessedAt: Long,

    /**
     * Version for optimistic locking (concurrency control)
     * Incremented on every update to detect conflicts
     */
    val version: Long = 0,

    /**
     * Schema version for migration support
     */
    val schemaVersion: Int = CURRENT_SCHEMA_VERSION
) {
    companion object {
        const val CURRENT_SCHEMA_VERSION = 1
        const val MIN_WEIGHT = 1
        const val MAX_WEIGHT = 16
        const val DEFAULT_WEIGHT = 8

        /**
         * Create a new memory with defaults
         */
        fun create(
            id: Long,
            content: String,
            type: MemoryType = MemoryType.FACT,
            source: MemorySource = MemorySource.TEXT,
            timestamp: Long = System.currentTimeMillis()
        ): MemoryItem {
            return MemoryItem(
                id = id,
                content = content,
                normalizedContent = normalizeContent(content),
                type = type,
                state = ProcessingState.NEW,
                weight = DEFAULT_WEIGHT,
                isPinned = false,
                confidence = null,
                isCompleted = false,
                accessCount = 0,
                embedding = null,
                source = source,
                tags = emptyList(),
                createdAt = timestamp,
                updatedAt = timestamp,
                lastAccessedAt = timestamp
            )
        }

        /**
         * Basic content normalization
         */
        private fun normalizeContent(content: String): String {
            return content
                .trim()
                .lowercase()
                .replace(Regex("\\s+"), " ")
        }
    }

    /**
     * Check if memory is eligible for decay
     */
    fun canDecay(): Boolean {
        return !isPinned && 
               state.canBeOptimized && 
               weight > MIN_WEIGHT
    }

    /**
     * Check if memory should be archived
     */
    fun shouldArchive(): Boolean {
        return weight <= MIN_WEIGHT && 
               !isPinned && 
               state == ProcessingState.OPTIMIZED
    }

    /**
     * Check if memory is searchable
     */
    fun isSearchable(): Boolean {
        return state in ProcessingState.searchable()
    }

    /**
     * Days since last access
     */
    fun daysSinceAccess(now: Long): Int {
        val diffMs = now - lastAccessedAt
        return (diffMs / (24 * 60 * 60 * 1000)).toInt()
    }

    /**
     * Days since creation
     */
    fun age(now: Long): Int {
        val diffMs = now - createdAt
        return (diffMs / (24 * 60 * 60 * 1000)).toInt()
    }

    // ========== Mutation helpers (return new instances) ==========

    fun withWeight(newWeight: Int): MemoryItem {
        return copy(
            weight = newWeight.coerceIn(MIN_WEIGHT, MAX_WEIGHT),
            updatedAt = System.currentTimeMillis(),
            version = version + 1
        )
    }

    fun withState(newState: ProcessingState): MemoryItem {
        require(state.canTransitionTo(newState)) {
            "Invalid state transition: $state -> $newState"
        }
        return copy(
            state = newState,
            updatedAt = System.currentTimeMillis(),
            version = version + 1
        )
    }

    fun withAccess(now: Long = System.currentTimeMillis()): MemoryItem {
        return copy(
            accessCount = accessCount + 1,
            lastAccessedAt = now,
            updatedAt = now,
            version = version + 1
        )
    }

    fun withPin(pinned: Boolean): MemoryItem {
        return copy(
            isPinned = pinned,
            updatedAt = System.currentTimeMillis(),
            version = version + 1
        )
    }

    fun withCompletion(completed: Boolean): MemoryItem {
        require(type == MemoryType.TASK) {
            "Only TASK type can have completion state"
        }
        return copy(
            isCompleted = completed,
            updatedAt = System.currentTimeMillis(),
            version = version + 1
        )
    }

    fun withConfidence(rating: Int?): MemoryItem {
        require(rating == null || rating in 1..5) {
            "Confidence must be 1-5 or null"
        }
        return copy(
            confidence = rating,
            updatedAt = System.currentTimeMillis(),
            version = version + 1
        )
    }

    fun withEmbedding(vector: ByteArray): MemoryItem {
        return copy(
            embedding = vector,
            updatedAt = System.currentTimeMillis(),
            version = version + 1
        )
    }

    fun withTags(newTags: List<String>): MemoryItem {
        return copy(
            tags = newTags.distinct(),
            updatedAt = System.currentTimeMillis(),
            version = version + 1
        )
    }

    fun withNormalizedContent(normalized: String): MemoryItem {
        return copy(
            normalizedContent = normalized,
            updatedAt = System.currentTimeMillis(),
            version = version + 1
        )
    }

    fun withType(newType: MemoryType): MemoryItem {
        return copy(
            type = newType,
            updatedAt = System.currentTimeMillis(),
            version = version + 1
        )
    }

    fun withVersion(newVersion: Long): MemoryItem {
        return copy(version = newVersion)
    }

    fun withAccessCount(count: Int): MemoryItem {
        return copy(
            accessCount = count,
            updatedAt = System.currentTimeMillis()
        )
    }

    fun withLastAccessedAt(timestamp: Long): MemoryItem {
        return copy(lastAccessedAt = timestamp)
    }

    fun markDirty(): MemoryItem {
        return copy(
            state = ProcessingState.DIRTY,
            updatedAt = System.currentTimeMillis(),
            version = version + 1
        )
    }

    fun markTombstoned(): MemoryItem {
        return copy(
            state = ProcessingState.TOMBSTONED,
            updatedAt = System.currentTimeMillis(),
            version = version + 1
        )
    }
}

/**
 * Source of memory input
 */
enum class MemorySource {
    TEXT,       // Manual text entry
    VOICE,      // Voice transcription
    IMPORT,     // Imported from external source
    MERGED,     // Result of merging similar memories
    SYSTEM      // System-generated
}
